package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.web.context.request.RequestAttributes;
import org.springframework.web.context.request.RequestContextHolder;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The request attribute naming the steward a user delegated the steward role acts for: each line of a
     *  change they make ends with for=<steward>, but for the lines that only report figures. */
    public static final String ACTING_FOR = Audit.class.getName() + ".actingFor";

    /** The events that only report figures, and so carry no for=. */
    private static final String[] FIGURES = { "ROLLUP ", "TOTALS ", "ALERT " };

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back (by any rule) writes nothing. Outside a transaction the record is written now.
     */
    public void recordOnCommit(String line) {
        String entry = line + actingFor(line);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    private static String actingFor(String entry) {
        RequestAttributes request = RequestContextHolder.getRequestAttributes();
        Object steward = request == null ? null : request.getAttribute(ACTING_FOR, RequestAttributes.SCOPE_REQUEST);
        if (steward == null) {
            return "";
        }
        for (String figures : FIGURES) {
            if (entry.startsWith(figures)) {
                return "";
            }
        }
        return " for=" + steward;
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.holiday;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** A sheet's list of holidays. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/holidays")
public class HolidayController {

    public record HolidayView(long id, String date) {

        static HolidayView of(Holiday h) {
            return new HolidayView(h.getId(), h.getDate().toString());
        }
    }

    public record HolidayRequest(@NotNull LocalDate date) {
    }

    private final HolidayService service;

    public HolidayController(HolidayService service) {
        this.service = service;
    }

    /** The sheet's holidays, earliest first. */
    @GetMapping
    public List<HolidayView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return service.list(sheetId.trim()).stream().map(HolidayView::of).toList();
    }

    /** Add a date to the sheet's holidays. */
    @PostMapping
    public HolidayView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid HolidayRequest request) {
        return HolidayView.of(service.add(sheetId.trim(), user.trim(), request.date()));
    }

    /** A holiday that cannot be added is refused with the reason, for the screen to show. */
    @ExceptionHandler(HolidayRefusedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> refused(HolidayRefusedException e) {
        return Map.of("message", e.getMessage());
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, isDate } from './session';

/** A holiday on the sheet's list (YYYY-MM-DD). */
export interface HolidayView {
  id: number;
  date: string;
}

// The active sheet's holidays, re-read from the server each time the sheet is loaded. A claim added whose
// date plus its terms falls on one is due by the next day that is not one; a holiday added later leaves the
// due-by dates already fixed as they are.
@Injectable({ providedIn: 'root' })
export class Holidays {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** Earliest first. */
  readonly holidays = signal<HolidayView[]>([]);
  private loads = 0;

  /** Re-read the active sheet's holidays from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.holidays.set([]);
    if (!user || !sid) return null;
    try {
      const holidays = await firstValueFrom(
        this.http.get<HolidayView[]>(this.url(sid), { headers: { 'X-User': user } }),
      );
      if (load === this.loads) this.holidays.set(holidays);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not load holidays (${e.status}).` : 'Could not load holidays.';
    }
  }

  /** Add a date to the sheet's holidays; an error message when refused. */
  async add(date: string): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const d = date.trim();
    if (!user || !sid) return 'Load a sheet first.';
    if (!isDate(d)) return 'Enter the date as YYYY-MM-DD.';
    try {
      const saved = await firstValueFrom(
        this.http.post<HolidayView>(this.url(sid), { date: d }, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) {
        this.holidays.update((hs) => [...hs.filter((h) => h.date !== saved.date), saved]
          .sort((a, b) => a.date.localeCompare(b.date)));
      }
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && typeof e.error?.message === 'string') return e.error.message;
      if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter the date as YYYY-MM-DD.';
      return e instanceof HttpErrorResponse ? `Could not add holiday (${e.status}).` : 'Could not add holiday.';
    }
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/holidays`;
  }
}
import { Component, inject, signal } from '@angular/core';
import { Holidays } from '../../core/holidays';

// The sheet's holidays: a form adds a date (one already on the list is refused), and the list shows them,
// earliest first. A claim's due-by, fixed when it is added, counts business days past the weekends and the
// holidays listed then.
@Component({
  selector: 'app-holidays',
  template: `
    <section aria-label="Holidays" data-testid="holidays">
      <h2>Holidays</h2>
      <form (submit)="add($event)" data-testid="holiday-form">
        <label for="holiday-date">Date (YYYY-MM-DD)</label>
        <input
          id="holiday-date"
          data-testid="holiday-date"
          placeholder="YYYY-MM-DD"
          [value]="date()"
          (input)="date.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="holiday-add" [disabled]="saving()">Add holiday</button>
        @if (error(); as err) {
          <p role="alert" data-testid="holiday-error">{{ err }}</p>
        }
      </form>
      <ul data-testid="holiday-list" aria-label="Holidays">
        @for (h of holidays.holidays(); track h.id) {
          <li [attr.data-testid]="'holiday-row-' + h.date">{{ h.date }}</li>
        }
      </ul>
    </section>
  `,
})
export class HolidaysPanel {
  protected readonly holidays = inject(Holidays);
  protected readonly date = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.saving()) return; // a second submit before the first has answered
    this.error.set(null);
    this.saving.set(true);
    try {
      const err = await this.holidays.add(this.date());
      if (err) this.error.set(err);
      else this.date.set('');
    } finally {
      this.saving.set(false);
    }
  }
}
